//! DDL type strings parse and print exactly as in Spark 4.2.0
//! (`tests/fixtures/spark-4.2.0/type-strings.json`, generated by
//! `tests/scripts/gen_type_strings.py` from a real Spark run).
#![expect(clippy::panic, reason = "test helpers sit outside #[test] fns")]

use std::collections::BTreeMap;
use std::path::PathBuf;

use arrow_schema::DataType as ArrowType;
use krishiv_common::error::{ErrorClass, KrishivError};
use krishiv_types::{DataType, DecimalType, parse_data_type};
use serde_json::Value;

/// Spark types that parse in Spark but are out of scope here; Krishiv
/// rejects them with `KRISHIV_UNSUPPORTED_FEATURE`.
const OUT_OF_SCOPE: &[&str] = &[
    "void",
    "array<int>",
    "map<string,int>",
    "struct<a:int>",
    "char(5)",
    "varchar(10)",
    "interval year to month",
    "interval day to second",
    "variant",
    "time",
    "string collate utf8_lcase",
];

/// Inputs where Spark fails without an error class; Krishiv raises the
/// class named here instead.
const UNCLASSIFIED_IN_SPARK: &[(&str, ErrorClass)] = &[(
    "decimal(99999999999,0)",
    ErrorClass::DecimalPrecisionExceedsMaxPrecision,
)];

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/spark-4.2.0/type-strings.json");
    let text =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("parse fixture: {e}"))
}

fn cases<'a>(doc: &'a Value, key: &str) -> &'a [Value] {
    doc.get(key)
        .and_then(Value::as_array)
        .map_or(&[], Vec::as_slice)
}

fn text<'a>(case: &'a Value, key: &str) -> &'a str {
    case.get(key)
        .and_then(Value::as_str)
        .unwrap_or_else(|| panic!("{key} missing in {case}"))
}

fn assert_renders(t: &DataType, case: &Value) {
    assert_eq!(t.simple_string(), text(case, "simple_string"), "{case}");
    assert_eq!(t.catalog_string(), text(case, "catalog_string"), "{case}");
    assert_eq!(t.sql(), text(case, "sql"), "{case}");
    assert_eq!(t.type_name(), text(case, "type_name"), "{case}");
    let reparsed = parse_data_type(text(case, "simple_string"));
    assert_eq!(reparsed.as_ref(), Ok(t), "{case}");
}

/// Our error matches Spark's class, SQLSTATE and message parameters.
fn assert_spark_error(e: &KrishivError, case: &Value) {
    assert_eq!(e.error_class().name(), text(case, "error_class"), "{case}");
    let state = case
        .get("sql_state")
        .and_then(Value::as_str)
        .filter(|s| !s.is_empty());
    assert_eq!(e.sql_state(), state, "{case}");
    let ours: BTreeMap<&str, &str> = e
        .message_parameters()
        .iter()
        .map(|(k, v)| (*k, v.as_str()))
        .collect();
    let spark: BTreeMap<&str, &str> = case
        .get("message_parameters")
        .and_then(Value::as_object)
        .map(|m| {
            m.iter()
                .filter_map(|(k, v)| Some((k.as_str(), v.as_str()?)))
                .collect()
        })
        .unwrap_or_default();
    assert_eq!(ours, spark, "{case}");
}

#[test]
fn ddl_strings_match_spark() {
    let doc = fixture();
    assert_eq!(
        doc.get("spark_version").and_then(Value::as_str),
        Some("4.2.0")
    );
    let ddl = cases(&doc, "ddl");
    assert!(ddl.len() >= 90, "fixture has {} DDL cases", ddl.len());
    let mut in_scope = std::collections::BTreeSet::new();
    for case in ddl {
        let input = text(case, "ddl");
        let ours = parse_data_type(input);
        let spark_class = case.get("error_class").and_then(Value::as_str);
        match (spark_class, &ours) {
            (None, Ok(t)) => {
                assert_renders(t, case);
                in_scope.insert(t.simple_string());
            }
            (None, Err(e)) => {
                assert!(OUT_OF_SCOPE.contains(&input), "{input:?}: {e}");
                assert_eq!(e.error_class(), ErrorClass::KrishivUnsupportedFeature);
            }
            (Some("UNCLASSIFIED"), _) => {
                let expected = UNCLASSIFIED_IN_SPARK
                    .iter()
                    .find(|(i, _)| *i == input)
                    .map(|(_, c)| *c);
                assert!(expected.is_some(), "{input:?}");
                assert_eq!(ours.map_err(|e| e.error_class()).err(), expected);
            }
            (Some(_), Ok(t)) => panic!("{input:?} parsed as {t} but Spark fails: {case}"),
            (Some(_), Err(e)) => assert_spark_error(e, case),
        }
    }
    // Every in-scope type appears in the fixture.
    for t in [
        "boolean",
        "tinyint",
        "smallint",
        "int",
        "bigint",
        "float",
        "double",
        "string",
        "binary",
        "decimal(10,0)",
        "decimal(38,38)",
        "date",
        "timestamp",
        "timestamp_ntz",
    ] {
        assert!(in_scope.contains(t), "{t} missing from fixture");
    }
}

#[test]
fn decimal_bounds_match_spark() {
    for case in cases(&fixture(), "decimal_constructor") {
        let p = case.get("precision").and_then(Value::as_i64).unwrap_or(-1);
        let s = case.get("scale").and_then(Value::as_i64).unwrap_or(-1);
        let ours = match (u32::try_from(p), u32::try_from(s)) {
            (Ok(p), Ok(s)) => DecimalType::try_new(p, s).map(DataType::Decimal),
            // A negative scale only reaches Krishiv through Arrow.
            _ => DataType::from_arrow(&ArrowType::Decimal128(
                u8::try_from(p).unwrap_or(0),
                i8::try_from(s).unwrap_or(0),
            )),
        };
        match (case.get("error_class"), ours) {
            (None, Ok(t)) => assert_renders(&t, case),
            (Some(_), Err(e)) => assert_spark_error(&e, case),
            (_, other) => panic!("decimal({p},{s}): {other:?} vs {case}"),
        }
    }
}

#[test]
fn decimal_38_38_ok_and_39_0_errors_with_spark_class() {
    assert!(parse_data_type("DECIMAL(38, 38)").is_ok());
    let e = parse_data_type("DECIMAL(39, 0)").err();
    assert_eq!(
        e.as_ref().map(KrishivError::error_class),
        Some(ErrorClass::DecimalPrecisionExceedsMaxPrecision)
    );
    assert_eq!(
        e.map(|e| e.to_string()).as_deref(),
        Some(
            "[DECIMAL_PRECISION_EXCEEDS_MAX_PRECISION] Decimal precision 39 exceeds max \
             precision 38. SQLSTATE: 22003"
        )
    );
}
